# Theme hook for bash: source this from ~/.bashrc.
# Points starship and fastfetch at the copies generated by ~/.config/theme/apply.
# Without them, the stowed configs (desktop palette) are used as they are.

__theme_state="$HOME/.local/state/theme"
[ -f "$__theme_state/starship.toml" ] && export STARSHIP_CONFIG="$__theme_state/starship.toml"
[ -f "$__theme_state/fastfetch.jsonc" ] && alias fastfetch="fastfetch -c '$__theme_state/fastfetch.jsonc'"
unset __theme_state
